def adjacent_num_product(list_nums):
    """Write a python function to find the largest product of the pair of adjacent elements from a given list of integers."""
    if len(list_nums) < 2:
        raise ValueError("list_nums must contain at least two elements")
    return max(
        list_nums[i] * list_nums[i + 1] for i in range(len(list_nums) - 1)
